import bisect

class Solution:
    def aggregateTimeSeries(self, series1: list[list[int]], series2: list[list[int]]) -> list[list[int]]:
        # Get all unique timestamps
        timestamps = set()
        for timestamp, _ in series1:
            timestamps.add(timestamp)
        for timestamp, _ in series2:
            timestamps.add(timestamp)

        timestamps = sorted(list(timestamps))

        # Create a helper function to get value at timestamp from a series using binary search
        def get_value_at_timestamp(series, target_timestamp):
            # Find the first timestamp >= target_timestamp
            idx = bisect.bisect_left(series, [target_timestamp, 0])
            if idx < len(series):
                return series[idx][1]
            return 0

        result = []
        for timestamp in timestamps:
            value1 = get_value_at_timestamp(series1, timestamp)
            value2 = get_value_at_timestamp(series2, timestamp)
            result.append([timestamp, value1 + value2])

        return result

