class Solution:
    def aggregateTimeSeries(self, series1: list[list[int]], series2: list[list[int]]) -> list[list[int]]:
        def getValueAtTimestamp(series, timestamp):
            # Binary search for the rightmost timestamp <= given timestamp
            # If found, return that value; otherwise, return 0 if no timestamp exists
            left, right = 0, len(series) - 1
            found_value = 0

            while left <= right:
                mid = (left + right) // 2
                if series[mid][0] <= timestamp:
                    found_value = series[mid][1]
                    left = mid + 1
                else:
                    right = mid - 1

            return found_value

        # Get all unique timestamps
        all_timestamps = set()
        for timestamp, _ in series1:
            all_timestamps.add(timestamp)
        for timestamp, _ in series2:
            all_timestamps.add(timestamp)

        # Convert to sorted list
        sorted_timestamps = sorted(all_timestamps)

        # Calculate aggregated series
        result = []
        for timestamp in sorted_timestamps:
            value1 = getValueAtTimestamp(series1, timestamp)
            value2 = getValueAtTimestamp(series2, timestamp)
            result.append([timestamp, value1 + value2])

        return result

class Solution:
    def isAsciiPalindromic(self, s: str) -> bool:
        # Convert each character to 8-bit binary representation
        binary_string = ""
        for char in s:
            # Get ASCII value and convert to 8-bit binary with leading zeros
            binary_representation = format(ord(char), '08b')
            binary_string += binary_representation

        # Check if the binary string is a palindrome
        return binary_string == binary_string[::-1]

