class Solution:
    def countGoodStrings(self, n: int) -> int:
        MOD = 10**9 + 7

        # Handle base cases
        if n == 1:
            return 2
        elif n == 2:
            return 2  
        elif n == 3:
            return 4
        elif n == 4:
            return 6

        # Matrix exponentiation approach
        # Matrix T = [[1, 1], [1, 0]]
        # For n >= 2, we use T^(n-2) * [2, 2] where 2,2 are the base values from n=2

        def matrix_mult(A, B):
            return [[(A[0][0]*B[0][0] + A[0][1]*B[1][0]) % MOD,
                     (A[0][0]*B[0][1] + A[0][1]*B[1][1]) % MOD],
                    [(A[1][0]*B[0][0] + A[1][1]*B[1][0]) % MOD,
                     (A[1][0]*B[0][1] + A[1][1]*B[1][1]) % MOD]]

        def matrix_power(mat, power):
            if power == 1:
                return mat
            if power % 2 == 0:
                half = matrix_power(mat, power // 2)
                return matrix_mult(half, half)
            else:
                return matrix_mult(mat, matrix_power(mat, power - 1))

        # The transition matrix 
        T = [[1, 1], [1, 0]]
        # Initial [a_2, b_2] = [2, 2]  
        initial = [2, 2] 

        # Compute T^(n-2)
        result_matrix = matrix_power(T, n - 2)

        # [a_n, b_n] = result_matrix * [a_2, b_2]
        a_n = (result_matrix[0][0] * initial[0] + result_matrix[0][1] * initial[1]) % MOD
        b_n = (result_matrix[1][0] * initial[0] + result_matrix[1][1] * initial[1]) % MOD

        return (a_n + b_n) % MOD
